import java.io.*;
import java.util.*;

public class Main {
    static final InputStream IN = System.in;
    static final byte[] BUF = new byte[1 << 16];
    static int len, ptr;

    static int readByte() throws IOException {
        if (ptr == len) {
            len = IN.read(BUF, 0, BUF.length);
            ptr = 0;
            if (len <= 0) {
                len = 0;
                return -1;
            }
        }
        return BUF[ptr++];
    }

    static long nextLong() throws IOException {
        int c = readByte();
        while (c == ' ' || c == '\n' || c == '\r' || c == '\t') c = readByte();
        boolean neg = c == '-';
        if (neg) c = readByte();
        long v = 0;
        while (c >= '0' && c <= '9') {
            v = v * 10 + (c - '0');
            c = readByte();
        }
        return neg ? -v : v;
    }

    static int nextInt() throws IOException {
        return (int) nextLong();
    }

    static String next() throws IOException {
        int c = readByte();
        while (c == ' ' || c == '\n' || c == '\r' || c == '\t') c = readByte();
        StringBuilder sb = new StringBuilder();
        while (c > ' ') {
            sb.append((char) c);
            c = readByte();
        }
        return sb.toString();
    }

    public static void main(String[] args) throws IOException {
        int n = nextInt(), mid = n / 2;
        // Value counts inside the shape and in the background.
        long[] inside = new long[3], outside = new long[3];
        for (int r = 0; r < n; r++)
            for (int c = 0; c < n; c++) {
                int v = nextInt();
                boolean onShape = (r <= mid && (c == r || c == n - 1 - r)) || (r >= mid && c == mid);
                if (onShape) inside[v]++;
                else outside[v]++;
            }
        long best = Long.MAX_VALUE;
        for (int a = 0; a < 3; a++)
            for (int b = 0; b < 3; b++)
                if (a != b) best = Math.min(best, (long) n * n - inside[a] - outside[b]);
        System.out.println(best);
    }
}

package main

import (
	"fmt"
	"io"
	"os"
)

var data []byte
var pos int

// token returns the next whitespace-separated token of stdin.
func token() []byte {
	for pos < len(data) && data[pos] <= ' ' {
		pos++
	}
	start := pos
	for pos < len(data) && data[pos] > ' ' {
		pos++
	}
	return data[start:pos]
}

func nextInt() int {
	b := token()
	neg := len(b) > 0 && b[0] == '-'
	if neg {
		b = b[1:]
	}
	v := 0
	for _, c := range b {
		v = v*10 + int(c-'0')
	}
	if neg {
		return -v
	}
	return v
}

func main() {
	data, _ = io.ReadAll(os.Stdin)
	n := nextInt()
	mid := n / 2
	// Value counts inside the shape and in the background.
	var inside, outside [3]int
	for r := 0; r < n; r++ {
		for c := 0; c < n; c++ {
			v := nextInt()
			if (r <= mid && (c == r || c == n-1-r)) || (r >= mid && c == mid) {
				inside[v]++
			} else {
				outside[v]++
			}
		}
	}
	best := n * n
	for a := 0; a < 3; a++ {
		for b := 0; b < 3; b++ {
			if a != b {
				best = min(best, n*n-inside[a]-outside[b])
			}
		}
	}
	fmt.Println(best)
}
